  "发送服务号消息是指向已关注服务号的微信用户发送模版消息。发送对象支持使用人员字段（通过微信授权注册的外部门户用户）或文本字段（存储微信服务号openid）。使用微信服务号模板消息需要组织后台绑定已认证的企业服务号，并在微信服务号后台开通“模板消息”功能。": "",
