  "编号=开始值+创建记录数-1。若修改开始值，则之后的编号将根据新的开始值计算。例如，原来的开始值为1，已创建记录数为10，则当前最后一条编号为no.10；若此时将开始值修改为10，则下一条记录的编号为no.20。": "",
