  "选择扩展信息表中作为用户权限标签的字段，仅支持关联记录类型的字段（最多可设置%0个字段）。当其他工作表的记录也关联了和用户相同的标签时，可以在角色中设置为用户对此记录拥有权限": "",
  "作为权限标签的扩展信息字段": "",
  "以下权限标签与其他权限的叠加方式为且。如设置权限标签【密级】，则表示必须密级同时也满足时才能拥有权限。当密级不匹配时，即使加入记录或满足其他标签时也没有权限。": "",
  "如在销售管理应用中": "",
